155	export function createOutputMetadata(evalRecord: Eval) {
156	  let evaluationCreatedAt: string | undefined;
157	  if (evalRecord.createdAt) {
158	    try {
159	      const date = new Date(evalRecord.createdAt);
160	      evaluationCreatedAt = Number.isNaN(date.getTime()) ? undefined : date.toISOString();
161	    } catch {
162	      evaluationCreatedAt = undefined;
163	    }
164	  }
165	
166	  return {
167	    promptfooVersion: VERSION,
168	    nodeVersion: process.version,
